#nullable enable // autogenerated

using PVZEngine.Tools.Unity;
using UnityEngine;

namespace MVZ2Logic.UI
{
    [DisallowMultipleComponent]
    [RequireComponent(typeof(MeshRenderer))]
    public class MeshRendererResolver : MonoBehaviour, ISpriteResolver
    {
        private void OnEnable()
        {
            UpdateResolver();
        }
        public void UpdateResolver()
        {
            if (!spriteChanged)
            {
                spriteChanged = true;
                BaseTexture = GetTexture();
            }
            SetTextureForced(BaseTexture);
        }
        public void SetTexture(Texture2D? texture)
        {
            if (texture == BaseTexture)
                return;
            SetTextureForced(texture);
        }
        public void SetTextureForced(Texture2D? texture)
        {
            var final = texture;
            if (Global.Resources != null && final != null)
            {
                final = Global.Resources.GetFinalTexture(final);
            }
            spriteChanged = true;
            BaseTexture = texture;
            if (final == BaseTexture)
                return;

            var propertyBlock = PropertyBlock;
            GetPropertyBlock(propertyBlock);
            propertyBlock.SetTexture("_MainTex", final);
            SetPropertyBlock(propertyBlock);
        }
        public virtual Texture2D? GetTexture()
        {
            return Renderer.sharedMaterial.GetTexture("_MainTex") as Texture2D;
        }
        public virtual void SetEnabled(bool enabled)
        {
            Renderer.enabled = enabled;
        }
        public void GetPropertyBlock(MaterialPropertyBlock propertyBlock)
        {
            Renderer.GetPropertyBlock(propertyBlock);
        }
        public void SetPropertyBlock(MaterialPropertyBlock propertyBlock)
        {
            Renderer.SetPropertyBlock(propertyBlock);
        }
        public Texture2D? BaseTexture { get; private set; }
        public MeshRenderer Renderer
        {
            get
            {
                if (!_renderer.Exists())
                {
                    _renderer = GetComponent<MeshRenderer>();
                }
                return _renderer;
            }
        }
        public MaterialPropertyBlock PropertyBlock
        {
            get
            {
                if (_propertyBlock == null)
                {
                    _propertyBlock = new MaterialPropertyBlock();
                }
                return _propertyBlock;
            }
        }
        public virtual int sortingOrder { get => Renderer.sortingOrder; set => Renderer.sortingOrder = value; }
        public virtual int sortingLayerID { get => Renderer.sortingLayerID; set => Renderer.sortingLayerID = value; }
        private MeshRenderer? _renderer;
        private MaterialPropertyBlock? _propertyBlock;
        private bool spriteChanged;
    }
}
